// Reviewer corpus for R-GP-IMPL-OWNER-ACT-FIELDS-1: owner values and
// altered-prose mutations of an owner-act record. Identical bytes are
// placed in the base and head clones; nothing here imports the subject.

const KEYWORDS = [
  'agent', 'bot', 'machine', 'service', 'system', 'ci', 'pipeline', 'model',
  'claude', 'codex', 'gpt', 'copilot', 'llm', 'daemon', 'automation', 'syzygy',
  '[bot]', 'Tzeusy', 'Somebody Else', 'Claudette',
];
const SEPS = ['', ' ', ':', '-', '/', '_', '.', '[', ']', 'x', '\t'];

const EXTRAS = [
  'Tzeusy', 'tzeusy', 'TZEUSY', ' Tzeusy', 'Tzeusy (via a Claude Code session)', 'Tzeusy, with codex',
  'Tzeusy - recorded by syzygy daemon', 'Tzeusy-bot', 'Tzeusy [bot]', 'Tzeusy[bot]', 'Tzeusy/ci', 'Tzeusy-agent',
  'Agent Tzeusy', 'Bot Tzeusy', 'renovate[bot]', 'dependabot[bot]', 'github-actions[bot]', 'gpt-5', 'GPT-4o',
  'Claude Opus', 'claude-code', 'Codex CLI', 'Copilot', 'an LLM', 'LLM-assisted Tzeusy', 'syzygy-daemon',
  'Syzygy daemon', 'machine-user', 'ci-runner', 'CI', 'system', 'Service Account', 'pipeline:nightly',
  'model: claude', 'daemon: poc', 'automation/release', 'deploy-bot', 'review-agent', 'Anna Model',
  'Jean-Botha', 'Botha', 'Agentha Smith', 'Somebody Else', '{{OWNER}}', 'agent/x', 'bot/x', 'system/x',
  'service/x', 'pipeline/x', 'model/x', 'machine/x', 'claude_x', 'x-bot', 'x-agent', 'robot', 'abbot',
];

export function ownerCorpus(): string[] {
  const set = new Set<string>(EXTRAS);
  for (const k of KEYWORDS) {
    for (const a of SEPS) {
      for (const b of SEPS) {
        set.add(a + k + b);
        set.add('name' + a + k + b);
        set.add(k + a + 'name' + b);
        set.add((a + k + b).toUpperCase());
      }
    }
  }
  return [...set].filter((value) => value.trim() === value || value === ' Tzeusy');
}

export function representativeOwners(): string[] {
  return [...EXTRAS];
}

export interface ProseMutation {
  readonly id: string;
  readonly extraHead?: readonly string[];
  readonly effect?: (original: string) => string;
  readonly text: (record: string, owner: string) => string;
}

const same = (record: string) => record;
const once = (record: string, from: string, to: string) => {
  if (!record.includes(from)) throw new Error(`prose mutation target absent: ${from}`);
  return record.replace(from, to);
};

export const PROSE_MUTATIONS: readonly ProseMutation[] = [
  { id: 'none', text: same },
  { id: 'title-claims-agent', text: (r) => once(r, '# Owner act — ', '# Owner act — drafted by agent: Claude Code — ') },
  {
    id: 'ceremony-intro-agent',
    text: (r) => once(r, 'The owner performed this one act by writing exactly:', "Claude Code performed this one act on the owner's behalf by writing exactly:"),
  },
  { id: 'effect-appended-agent-sentence', effect: (e) => `${e}\n\nThis act was drafted by codex and recorded by the syzygy daemon.`, text: same },
  { id: 'effect-paraphrased-no-anchors', effect: () => 'The owner consents to whatever the agent decides.', text: same },
  { id: 'effect-reflowed', effect: (e) => e.replace(/\n/g, ' '), text: same },
  { id: 'extra-head-recorded-by-agent', extraHead: ['Recorded by: agent: Claude Code'], text: same },
  { id: 'extra-head-duplicate-owner-codex', extraHead: ['Owner: codex'], text: same },
  { id: 'extra-head-duplicate-owner-daemon', extraHead: ['Owner: daemon'], text: same },
  { id: 'extra-head-note-bot', extraHead: ['Note: renovate[bot] opened the pull request.'], text: same },
  { id: 'owner-line-bold-label', text: (r, o) => once(r, `Owner: ${o}`, `**Owner:** ${o}`) },
  { id: 'owner-line-lowercase-label', text: (r, o) => once(r, `Owner: ${o}`, `owner: ${o}`) },
  { id: 'owner-line-continued', text: (r, o) => once(r, `Owner: ${o}`, `Owner: ${o}\n(via agent: Claude Code)`) },
  { id: 'owner-line-trailing-prose', text: (r, o) => once(r, `Owner: ${o}`, `Owner: ${o}, recorded in a Claude Code session`) },
  { id: 'not-authorize-altered', text: (r) => once(r, 'Nothing beyond its own authority.', 'Nothing; an LLM drafted this section.') },
  { id: 'body-owner-after-heading', text: (r) => `${r}\nOwner: codex\n\nOwner: daemon\n` },
];

