// ---------------------------------------------------------------------
// Reviewer differential harness (R-GP-IMPL-OWNER-ACT-FIELDS-1), appended
// to a verbatim copy of the fixture section of body-read-authority.test.ts.
// Evaluates a mutated-record corpus (owner values x altered prose x
// expected-owner modes) and writes one JSON line per evaluation to
// $REVIEWER_DIFF_OUT. Run identically at base and head; compare outside.
// ---------------------------------------------------------------------
import { writeFileSync as reviewerWrite } from 'node:fs';
import { ownerCorpus, representativeOwners, PROSE_MUTATIONS } from './zz-reviewer-corpus.js';

describe('reviewer differential (body-read)', () => {
  it('evaluates the corpus', () => {
    const out: string[] = [];
    const kinds = ['consent', 'policy', 'registry'] as const;
    const record = (kind: AuthorityKind, owner: string, prose: (typeof PROSE_MUTATIONS)[number]) => {
      const digest = sha256(defaultArtifactText(kind));
      const meta = AUTHORITIES[kind];
      const overrides: RecordOverrides = {
        set: { 'Owner:': owner },
        ...(prose.extraHead ? { extraHead: prose.extraHead } : {}),
        ...(prose.effect ? { effect: prose.effect(meta.effect) } : {}),
      };
      return prose.text(actRecord(kind, digest, overrides), owner);
    };
    const run = (owners: readonly string[], proses: typeof PROSE_MUTATIONS) => {
      for (const prose of proses) {
        for (const owner of owners) {
          for (const kind of kinds) {
            for (const mode of ['production-owner', 'owner-equals-expected'] as const) {
              const exp = { ...expectations(), owner: mode === 'production-owner' ? OWNER : owner };
              const text = record(kind, owner, prose);
              const evaluation = evaluateBodyReadAuthority(
                inputs({ [kind]: { actRecord: { kind: 'owner-act-record', text } }, expectations: exp }),
              );
              const state = evaluation[kind];
              out.push(
                JSON.stringify({
                  gate: 'body-read',
                  prose: prose.id,
                  owner,
                  kind,
                  mode,
                  state: state.kind,
                  caseId: state.kind === 'invalid' ? state.caseId : null,
                  admits: evaluation.admits,
                }),
              );
            }
          }
        }
      }
    };
    run(ownerCorpus(), PROSE_MUTATIONS.filter((p) => p.id === 'none'));
    run(representativeOwners(), PROSE_MUTATIONS.filter((p) => p.id !== 'none'));
    reviewerWrite(process.env.REVIEWER_DIFF_OUT ?? '/dev/null', out.join('\n') + '\n');
    expect(out.length).toBeGreaterThan(0);
  }, 600_000);
});

